package behavioral.command.sample;

public interface ICommand {
    void execute();
}

package behavioral.command.sample;

public class Main {

    public static void main(String[] args) {
        RemoteControl remote = new RemoteControl();

        TV tv1 = new TV("TV 1");
        ICommand turnOnV1 = new TurnTVOnCommand(tv1);
        ICommand turnOffV1 = new TurnTVOffCommand(tv1);
        remote.setCommand(turnOnV1);
        remote.pressButton();
        remote.setCommand(turnOffV1);
        remote.pressButton();

        TV tv2 = new TV("TV 2");
        ICommand turnOnV2 = new TurnTVOnCommand(tv2);
        ICommand turnOffV2 = new TurnTVOffCommand(tv2);
        remote.setCommand(turnOnV2);
        remote.pressButton();
        remote.setCommand(turnOffV2);
        remote.pressButton();
    }
}

package behavioral.command.sample;

public class RemoteControl {
    private ICommand command;

    public void setCommand(ICommand command) {
        this.command = command;
    }

    public void pressButton() {
        command.execute();
    }
}

package behavioral.command.sample;

public class TV {
    private final String name;

    public TV(String name){
        this.name = name;
    }

    public void turnOn() {
        System.out.println("Turning " + this.name + " ON");
    }

    public void turnOff() {
        System.out.println("Turning " + this.name + " OFF");
    }
}

package behavioral.command.sample;

public class TurnTVOffCommand implements ICommand {
    private final TV tv;

    public TurnTVOffCommand(TV tv) {
        this.tv = tv;
    }

    @Override
    public void execute() {
        tv.turnOff();
    }
}

package behavioral.command.sample;

public class TurnTVOnCommand implements ICommand {
    private final TV tv;

    public TurnTVOnCommand(TV tv) {
        this.tv = tv;
    }

    @Override
    public void execute() {
        tv.turnOn();
    }
}

